import React from 'react';
import CatalogScreen from '../../src/screens/CatalogScreen';
export default function FavoritesRoute() { return <CatalogScreen mode="favorites" />; }

import React from 'react';
import CatalogScreen from '../../src/screens/CatalogScreen';
export default function HomeRoute() { return <CatalogScreen mode="home" />; }

import React from 'react';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useRouter } from 'expo-router';
import { PackageSearch } from 'lucide-react-native';
import { Button, EmptyState, Header } from '../src/ui/primitives';
import { colors, layout } from '../src/ui/theme';
export default function NotFound() {
  const router = useRouter();
  return <SafeAreaView style={layout.screen} edges={['top', 'left', 'right']}><Header title="Страница не найдена" back /><EmptyState icon={<PackageSearch size={34} color={colors.brand} />} title="Такой страницы нет" message="Ссылка могла устареть. Перейдите в каталог, чтобы продолжить." action={<Button label="Открыть каталог" onPress={() => router.replace('/catalog')} />} /></SafeAreaView>;
}

import React from 'react';
import CatalogScreen from '../../../src/screens/CatalogScreen';
export default function CatalogSection() { return <CatalogScreen nested />; }
